  static IEnumerator OriginalActionBrakeDiagnostic(Fixture f,Gamepad[] pads,Array players)
  {
   string path="Logs/TruckSports/PlaytestRepair/BakeOffControlledNative/"+Run+"/original-action-brake.txt";var trace=new System.Text.StringBuilder();float next=0,begin=Time.time;var entrySpeeds=f.trucks.Select(truck=>Body(truck).linearVelocity.magnitude).ToArray();var firstNativeBrake=Enumerable.Repeat(-1f,4).ToArray();
   object States(int i)=>Get(Get(Get(Get(f.trucks[i],"tractorMotor"),"vehicle"),"input"),"states");
   bool NativeHolding(int i)=>(bool)Call(f.match,"ActionHeld",i)&&(float)Get(States(i),"throttle")==0&&(float)Get(States(i),"handbrake")>.99f;
   void Observe(string phase,bool force=false)
   {
    if(!force&&Time.time<next)return;next=Time.time+.05f;
    for(int i=0;i<4;i++){var p=players.GetValue(i);var truck=f.trucks[i];var vehicle=Get(Get(truck,"tractorMotor"),"vehicle");var input=Get(vehicle,"input");var states=Get(input,"states");var body=Body(truck);trace.AppendLine("BAKE_ACTION_BRAKE phase="+phase+" age="+(Time.time-begin).ToString("R")+" frame="+Time.frameCount+" fixedTime="+Time.fixedTime.ToString("R")+" clock="+Get(f.rules,"Clock")+" owner="+i+" rawSouth="+pads[i].buttonSouth.isPressed+" rawRT="+pads[i].rightTrigger.ReadValue().ToString("R")+" source="+Get(p,"source")+" samePad="+ReferenceEquals(Get(p,"pad"),pads[i])+" enabled="+pads[i].enabled+" released="+Get(p,"released")+" actionHeld="+Call(f.match,"ActionHeld",i)+" command="+((Vector2[])Get(f.match,"commands"))[i]+" throttle="+Get(states,"throttle")+" brake="+Get(states,"brakes")+" handbrake="+Get(states,"handbrake")+" grounded="+Get(Get(truck,"tractorMotor"),"Grounded")+" velocity="+body.linearVelocity.ToString("F7")+" speed="+body.linearVelocity.magnitude.ToString("R")+" position="+body.position.ToString("F5")+" paused="+Get(f.match,"Paused"));}File.WriteAllText(path,trace.ToString());
   }
   Action afterUpdate=()=>{for(int i=0;i<4;i++)if(firstNativeBrake[i]<0&&NativeHolding(i))firstNativeBrake[i]=Time.time-begin;Observe("ACTUAL_INPUT_UPDATE");};
   try
   {
    Observe("BEFORE_ORIGINAL_SOUTH_EVENT",true);InputSystem.onAfterUpdate+=afterUpdate;
    for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState().WithButton(GamepadButton.South));
    // R14 measured7.11175 ->4.43609m/s in.50014s with the correct
    // original rear handbrake. Measure that response at the same half-second;
    // do not mistake an ordinary stopping distance for missing ACTION input.
    yield return new WaitForSeconds(.5f);Observe("ORIGINAL_HALF_SECOND_ASSERTION",true);
    for(int i=0;i<4;i++)
    {
     Assert.That(pads[i].buttonSouth.isPressed,Is.True);Assert.That(pads[i].rightTrigger.ReadValue(),Is.Zero);Assert.That((bool)Get(players.GetValue(i),"released"),Is.True);Assert.That(NativeHolding(i),Is.True,"Actual ACTION must command the original native handbrake with zero throttle.");Assert.That(firstNativeBrake[i],Is.GreaterThanOrEqualTo(0).And.LessThan(.5f),"The actual native handbrake must already have responded before the half-second measurement.");Assert.That(((Vector2[])Get(f.match,"commands"))[i],Is.EqualTo(Vector2.zero));
     Assert.That(Body(f.trucks[i]).linearVelocity.magnitude,Is.LessThan(entrySpeeds[i]),"The original rear handbrake must cause genuine physical deceleration from this actual powered-window entry speed.");
    }
    // The measured5.35m/s^2 response predicts<3 at.77s and<.7 at1.20s.
    // Allow at most TWO seconds TOTAL from the original South event, without
    // velocity writes, synthetic braking input, teleports or force changes.
    float realDeadline=Time.realtimeSinceStartup+3,belowThree=-1;
    while(f.trucks.Any(truck=>Body(truck).linearVelocity.magnitude>=.7f)&&Time.time-begin<2&&Time.realtimeSinceStartup<realDeadline)
    {
     if(belowThree<0&&f.trucks.All(truck=>Body(truck).linearVelocity.magnitude<3))belowThree=Time.time-begin;
     for(int i=0;i<4;i++)Assert.That(NativeHolding(i),Is.True,"Actual held ACTION must keep native handbrake/zero throttle during physical settling.");yield return null;
    }
    Observe("BOUNDED_PHYSICAL_STOP",true);
    if(belowThree<0&&f.trucks.All(truck=>Body(truck).linearVelocity.magnitude<3))belowThree=Time.time-begin;
    for(int i=0;i<4;i++){Assert.That(Body(f.trucks[i]).linearVelocity.magnitude,Is.LessThan(3),"Original speed criterion retained after bounded ordinary physical braking.");Assert.That(Body(f.trucks[i]).linearVelocity.magnitude,Is.LessThan(.7f),"Actual work adjustment must settle within two seconds, not merely coast below the original three-metre-per-second criterion.");}
    var settled=f.trucks.Select(truck=>Body(truck).position).ToArray();yield return new WaitForSeconds(.2f);Observe("ACTUAL_HELD_ADJUSTMENT_DRIFT",true);
    for(int i=0;i<4;i++){Assert.That(NativeHolding(i),Is.True);Assert.That(Body(f.trucks[i]).linearVelocity.magnitude,Is.LessThan(.7f));Assert.That(Vector3.Distance(settled[i],Body(f.trucks[i]).position),Is.LessThan(.2f),"Actual settled original rig must hold its work position under ACTION.");}
    for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState());
    yield return Until(()=>Enumerable.Range(0,4).All(i=>!(bool)Call(f.match,"ActionHeld",i)&&((Vector2[])Get(f.match,"commands"))[i]==Vector2.zero&&(float)Get(States(i),"throttle")==0&&(float)Get(States(i),"handbrake")==0),2,"Real neutral pad release must clear ACTION's native handbrake without restoring stale throttle.");
    yield return new WaitForSeconds(.2f);Observe("ACTUAL_NEUTRAL_RELEASE_NO_STALE_THROTTLE",true);
    for(int i=0;i<4;i++){Assert.That(pads[i].buttonSouth.isPressed,Is.False);Assert.That(pads[i].rightTrigger.ReadValue(),Is.Zero);Assert.That((float)Get(States(i),"throttle"),Is.Zero);Assert.That((float)Get(States(i),"handbrake"),Is.Zero);Assert.That(Body(f.trucks[i]).linearVelocity.magnitude,Is.LessThan(.7f),"Releasing the adjustment must not replay the earlier powered drive command.");}
    TestContext.WriteLine("BAKE_REAL_REAR_HANDBRAKE entrySpeeds="+string.Join(",",entrySpeeds.Select(value=>value.ToString("R")))+" firstNativeBrakeSeconds="+string.Join(",",firstNativeBrake.Select(value=>value.ToString("R")))+" allBelowOriginal3At="+belowThree+"; originalhalf-secondresponse+boundedphysicalsettle+helddrift+actualreleaseobserved, no productionforce/speedchanges.");
   }
   finally{InputSystem.onAfterUpdate-=afterUpdate;Observe("DIAGNOSTIC_EXIT",true);}
  }
  static IEnumerator OriginalPoweredWindowReady(Fixture f,Gamepad[] pads,Array players)
  {
   string path="Logs/TruckSports/PlaytestRepair/BakeOffControlledNative/"+Run+"/original-nwh-startup-input.txt";var trace=new System.Text.StringBuilder();float next=0;
   object Engine(int i)=>Get(Get(Get(Get(f.trucks[i],"tractorMotor"),"vehicle"),"powertrain"),"engine");
   void Observe(string phase,bool force=false)
   {
    if(!force&&Time.realtimeSinceStartup<next)return;next=Time.realtimeSinceStartup+.25f;
    for(int i=0;i<4;i++){var p=players.GetValue(i);var vehicle=Get(Get(f.trucks[i],"tractorMotor"),"vehicle");var states=Get(Get(vehicle,"input"),"states");var e=Engine(i);trace.AppendLine("BAKE_STARTUP phase="+phase+" frame="+Time.frameCount+" clock="+Get(f.rules,"Clock")+" owner="+i+" source="+Get(p,"source")+" samePad="+ReferenceEquals(Get(p,"pad"),pads[i])+" enabled="+pads[i].enabled+" rawRT="+pads[i].rightTrigger.ReadValue().ToString("R")+" rawLT="+pads[i].leftTrigger.ReadValue().ToString("R")+" south="+pads[i].buttonSouth.isPressed+" released="+Get(p,"released")+" ready="+Call(f.match,"Ready",i)+" readDrive="+Call(f.match,"ReadDrive",i)+" command="+((Vector2[])Get(f.match,"commands"))[i]+" throttle="+Get(states,"throttle")+" brake="+Get(states,"brakes")+" handbrake="+Get(states,"handbrake")+" autoStart="+Get(e,"autoStartOnThrottle")+" running="+Get(e,"IsRunning")+" starter="+Get(e,"starterActive")+" rpmPercent="+Get(e,"RPMPercent")+" gear="+Get(Get(Get(vehicle,"powertrain"),"transmission"),"Gear")+" paused="+Get(f.match,"Paused")+" screen="+Get(Get(f.match,"menus"),"Screen"));}
    File.WriteAllText(path,trace.ToString());
   }
   try
   {
    // Actual Session.Update must observe neutral controls after StartMatch.Gate.
    // Countdown alone does not prove this per-driver release boundary.
    float end=Time.realtimeSinceStartup+8;
    while(!((bool)Get(f.rules,"Active")&&players.Cast<object>().Take(4).All(p=>(bool)Get(p,"released")))&&Time.realtimeSinceStartup<end){for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState());Observe("NATIVE_NEUTRAL_GATE");yield return null;}
    Observe("NEUTRAL_GATE_END",true);Assert.That((bool)Get(f.rules,"Active")&&players.Cast<object>().Take(4).All(p=>(bool)Get(p,"released")),Is.True,"Actual countdown AND four neutral driver release gates must finish before throttle; no release-state injection.");
    end=Time.realtimeSinceStartup+2;
    while(!((Vector2[])Get(f.match,"commands")).Take(4).All(c=>c.y>.7f)&&Time.realtimeSinceStartup<end){for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState{rightTrigger=.8f});Observe("HELD_SOFTWARE_RT_TO_SESSION");yield return null;}
    Observe("COMMAND_GATE_END",true);Assert.That(((Vector2[])Get(f.match,"commands")).Take(4).All(c=>c.y>.7f),Is.True,"All four actual raw software triggers must reach their original Session commands before attributing any wait to NWH startup.");
    end=Time.realtimeSinceStartup+6;
    while(!Enumerable.Range(0,4).All(i=>(bool)Get(Engine(i),"IsRunning")&&!(bool)Get(Engine(i),"starterActive"))&&Time.realtimeSinceStartup<end){for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState{rightTrigger=.8f});Observe("ORIGINAL_NWH_STARTER");yield return null;}
    Observe("POWERED_WINDOW_READY",true);Assert.That(Enumerable.Range(0,4).All(i=>(bool)Get(Engine(i),"IsRunning")&&!(bool)Get(Engine(i),"starterActive")),Is.True,"All four ORIGINAL NWH engines must finish their actual throttle-driven starter sequence before measuring the unchanged1.5second powered drive window.");Assert.That(((Vector2[])Get(f.match,"commands")).Take(4).All(c=>c.y>.7f),Is.True);
   }
   finally{Observe("STARTUP_FIXTURE_EXIT",true);}
  }
