  [UnityTest,Timeout(35000)]public IEnumerator ActualSavedWristListenerReceivesVesselCallbacksThenOriginalPhysicalPickup(){using(var f=new Fixture()){yield return f.Load();f.Start(1);Time.timeScale=2;yield return Until(()=>{f.Observe();return Get(f.arms[0],"Held")!=null;},24,"Actual native wrist callback must open the original candidate/Grab path; no overlap or proximity pickup substitute.");var wrist=(Rigidbody)Get(f.arms[0],"grip");var observer=wrist.GetComponent<BakeWristContactDiagnosticObserver>();Assert.That(observer.vessels,Is.GreaterThan(0));Assert.That((int)Get(f.arms[0],"NativeCandidates"),Is.GreaterThan(0));var held=Get(f.arms[0],"Held");Assert.That(held,Is.SameAs(f.ingredients[0]));Assert.That((int)Get(held,"LastCarrier"),Is.Zero);Assert.That(Get(held,"Holder"),Is.SameAs(f.arms[0]));var joint=(ConfigurableJoint)Get(held,"attachment");Assert.That(joint.connectedBody,Is.SameAs(wrist));Assert.That(((float[,])Get(f.rules,"measured")).Cast<float>(),Is.All.Zero,"Physical pickup alone cannot fabricate ingredient measurement or score.");Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);}}
  [UnityTest,Timeout(45000)]public IEnumerator RealEggContactInsideBowlMeasuresOnceFloorMissBreaksWithoutScore(){using(var f=new Fixture()){yield return f.Load();f.Start(1);yield return Until(()=>(bool)Get(f.rules,"Active"),8,"Original actual countdown.");f.match.enabled=false;foreach(var truck in f.trucks)Call(truck,"Power",false);var bowl=Get(f.bowls[0],"vessel");var egg=f.ingredients[3];var rb=Body(egg);rb.position=Body(bowl).position+Vector3.up*5;rb.rotation=Quaternion.identity;rb.transform.SetPositionAndRotation(rb.position,rb.rotation);rb.linearVelocity=Vector3.down*2;Physics.SyncTransforms();yield return Until(()=>(int)Get(f.match,"NativeEggCracks")>0,5,"The actual fragile egg must strike the actual bowl through native PhysX.");float measured=((float[,])Get(f.rules,"measured"))[0,3];Assert.That(measured,Is.GreaterThan(.85f));yield return new WaitForSeconds(.4f);Assert.That(((float[,])Get(f.rules,"measured"))[0,3],Is.EqualTo(measured));var miss=f.ingredients[4];var missedBody=Body(miss);missedBody.position=new Vector3(-65,9,-60);missedBody.rotation=Quaternion.identity;missedBody.transform.SetPositionAndRotation(missedBody.position,missedBody.rotation);missedBody.linearVelocity=Vector3.down*6;Physics.SyncTransforms();yield return Until(()=>(bool)Get(miss,"Broken"),5,"Actual missed fragile ingredient must break on the native floor.");Assert.That(((float[,])Get(f.rules,"measured"))[0,3],Is.EqualTo(measured));Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);Assert.That(((Rigidbody[])Get(miss,"fragments")).Any(b=>b.gameObject.activeSelf&&!b.isKinematic),Is.True);yield return Capture(f.match,"actual-egg-bowl-and-missed-break-720",1280,720);f.match.enabled=true;}}
  [UnityTest,Timeout(65000)]public IEnumerator OneThroughFourActualViewsAndFourSoftwarePadsPreservePhysicalOwners(){using(var f=new Fixture()){yield return f.Load();Sports("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});var views=Get(f.match,"drivingViews");Call(views,"Select",1);for(int n=1;n<=4;n++){f.Start(n);yield return null;yield return null;var rally=Get(views,"rally");Assert.That(((int[])Get(rally,"owners")).Take(n),Is.EqualTo(Enumerable.Range(0,n)));var cameras=(Camera[])Get(f.match,"cameras");Assert.That(cameras.Length,Is.EqualTo(n));Assert.That(cameras.Sum(c=>c.rect.width*c.rect.height),Is.EqualTo(1).Within(.001f));for(int i=0;i<n;i++){object[]args={i,-1,null,null};Assert.That((bool)f.match.GetType().GetMethod("TryReadViewportCard").Invoke(f.match,args),Is.True);Assert.That((int)args[1],Is.EqualTo(i));Assert.That((string)args[2],Is.EqualTo("0 PTS"));}}yield return Capture(f.match,"four-view-real-owner-cards-720",1280,720);yield return Capture(f.match,"four-view-real-owner-cards-1080",1920,1080);Call(f.match,"SetupScreen");Set(Get(f.match,"setup"),"count",4);Call(f.match,"NormalizeSetup");var players=(Array)Get(Get(f.match,"setup"),"players");var pads=new Gamepad[4];for(int i=0;i<4;i++){pads[i]=f.Pad();var p=players.GetValue(i);Set(p,"source",Enum.Parse(p.GetType().GetField("source").FieldType,"WholeController"));Set(p,"pad",pads[i]);InputSystem.QueueStateEvent(pads[i],new GamepadState());}Assert.That((bool)Call(f.match,"StartMatch"),Is.True);yield return OriginalPoweredWindowReady(f,pads,players);var starts=f.trucks.Select(Body).Select(b=>b.position).ToArray();float motionEnd=Time.time+1.5f,nextMotion=Time.time;string motionPath="Logs/TruckSports/PlaytestRepair/BakeOffControlledNative/"+Run+"/original-nwh-software-motion.txt";var motion=new System.Text.StringBuilder();while(Time.time<motionEnd){if(Time.time>=nextMotion){nextMotion=Time.time+.25f;for(int i=0;i<4;i++){var vehicle=Get(Get(f.trucks[i],"tractorMotor"),"vehicle");var power=Get(vehicle,"powertrain");var engine=Get(power,"engine");var transmission=Get(power,"transmission");var states=Get(Get(vehicle,"input"),"states");motion.AppendLine("BAKE_ORIGINAL_NWH clock="+Get(f.rules,"Clock")+" owner="+i+" distance="+Vector3.Distance(starts[i],Body(f.trucks[i]).position).ToString("R")+" command="+((Vector2[])Get(f.match,"commands"))[i]+" engineRunning="+Get(engine,"IsRunning")+" starterActive="+Get(engine,"starterActive")+" rpmPercent="+Get(engine,"RPMPercent")+" gear="+Get(transmission,"Gear")+" throttle="+Get(states,"throttle")+" brake="+Get(states,"brakes")+" handbrake="+Get(states,"handbrake")+" speed="+Body(f.trucks[i]).linearVelocity.magnitude.ToString("R"));}File.WriteAllText(motionPath,motion.ToString());}yield return null;}for(int i=0;i<4;i++){Assert.That(((Vector2[])Get(f.match,"commands"))[i].y,Is.GreaterThan(.7f));Assert.That(Vector3.Distance(starts[i],Body(f.trucks[i]).position),Is.GreaterThan(.3f));Assert.That((string)Get(Get(f.trucks[i],"appearanceHost"),"ProfileId"),Is.EqualTo((string)Get(players.GetValue(i),"participantId")));}yield return OriginalActionBrakeDiagnostic(f,pads,players);TestContext.WriteLine("BAKE_SOFTWARE_INPUT_ONLY; physical devices/human/listening acceptance remains pending.");}}
